mapper.select:
SELECT sku, available_qty, reserved_qty FROM inventory_db.stock WHERE sku IN
#{sku}
ORDER BY sku

mapper.update:
UPDATE inventory_db.stock
SET available_qty = available_qty - #{qty},
reserved_qty = reserved_qty + #{qty}
WHERE sku = #{sku}
AND available_qty >= #{qty}

UPDATE inventory_db.stock
SET available_qty = available_qty + #{qty},
reserved_qty = reserved_qty - #{qty}
WHERE sku = #{sku}
AND reserved_qty >= #{qty}
